"use client";

import { useEffect, useState } from "react";
import { X, CheckCircle2, Loader2, Mail } from "lucide-react";
import { validateEmail, validateName } from "@/lib/client-validators";

export function NewsletterPopup() {
  const [visible, setVisible] = useState(false);
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [terms, setTerms] = useState(false);
  const [state, setState] = useState<"idle" | "loading" | "success" | "error">(
    "idle"
  );
  const [message, setMessage] = useState("");

  useEffect(() => {
    const t = setTimeout(() => setVisible(true), 8000);
    return () => clearTimeout(t);
  }, []);

  function close() {
    setVisible(false);
  }

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    const nameError = name.trim() ? validateName(name) : null;
    const emailError = validateEmail(email);
    if (nameError) {
      setState("error");
      setMessage(nameError);
      return;
    }
    if (emailError) {
      setState("error");
      setMessage(emailError);
      return;
    }
    if (!terms) {
      setState("error");
      setMessage("Please accept the terms to subscribe.");
      return;
    }
    setState("loading");
    try {
      const res = await fetch("/api/newsletter", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: email.trim(), name: name.trim() }),
      });
      if (res.ok) {
        setState("success");
        setMessage("Welcome aboard! Check your inbox soon.");
      } else {
        const data = await res.json().catch(() => ({}));
        if (res.status === 409) {
          setState("success");
          setMessage("You're already subscribed! Thank you.");
        } else {
          setState("error");
          setMessage(data.error ?? "Something went wrong. Please try again.");
        }
      }
    } catch {
      setState("error");
      setMessage("Network error. Please try again.");
    }
  }

  if (!visible) return null;

  return (
    <div className="fixed inset-x-0 bottom-0 z-[60] p-4 sm:p-0 sm:inset-auto sm:left-8 sm:bottom-6 sm:w-[440px]">
      <div className="rounded-3xl border border-border/80 bg-card/95 backdrop-blur-xl shadow-2xl shadow-black/15 overflow-hidden animate-slide-in-up">
        <div className="h-1.5 w-full bg-gradient-to-r from-brand-light via-brand-light/50 to-brand-light" />

        <div className="p-6 sm:p-7">
          <div className="flex items-start justify-between gap-4">
            <div className="space-y-1">
              <span className="inline-flex items-center gap-1.5 rounded-full bg-accent/10 px-3 py-1 text-[11px] font-bold uppercase tracking-wider text-accent-strong">
                <Mail className="w-3 h-3" /> Sagar&apos;s Weekly Dispatch
              </span>
              <h3 className="font-display text-2xl font-bold leading-snug tracking-tight text-foreground">
                One practical idea. Every week.
              </h3>
              <p className="text-xs text-muted-foreground leading-relaxed pt-1">
                Unfiltered thoughts on money, career, and intentional living — one practical idea, every week.
              </p>
            </div>
            <button
              type="button"
              onClick={close}
              aria-label="Close newsletter popup"
              className="p-1.5 rounded-full text-muted-foreground hover:bg-muted hover:text-foreground transition-colors shrink-0"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          {state === "success" ? (
            <div className="mt-6 flex items-center gap-3 p-4 rounded-2xl bg-emerald-500/10 border border-emerald-500/20 text-emerald-600 dark:text-emerald-400 text-sm font-medium">
              <CheckCircle2 className="w-5 h-5 shrink-0" />
              <span>{message}</span>
            </div>
          ) : (
            <form onSubmit={onSubmit} className="mt-5 space-y-3.5" noValidate>
              <div className="space-y-2.5">
                <input
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="First name"
                  aria-label="Your name"
                  className="w-full rounded-2xl border border-border bg-background/80 px-4 py-3 text-sm outline-none focus:ring-2 focus:ring-accent focus:border-accent transition-all placeholder:text-muted-foreground/60"
                />
                <div className="relative">
                  <Mail className="w-4 h-4 absolute left-4 top-1/2 -translate-y-1/2 text-muted-foreground/60" />
                  <input
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="Your best email address"
                    aria-label="Your email address"
                    className="w-full rounded-2xl border border-border bg-background/80 pl-11 pr-4 py-3 text-sm outline-none focus:ring-2 focus:ring-accent focus:border-accent transition-all placeholder:text-muted-foreground/60"
                  />
                </div>
              </div>

              <label className="flex items-start gap-2.5 text-xs text-muted-foreground cursor-pointer pt-0.5">
                <input
                  type="checkbox"
                  checked={terms}
                  onChange={(e) => setTerms(e.target.checked)}
                  className="mt-0.5 h-4 w-4 rounded border-border accent-accent shrink-0"
                />
                <span className="leading-normal">
                  I agree to the{" "}
                  <a
                    href="/terms"
                    className="text-accent-strong underline underline-offset-2 hover:opacity-80"
                    onClick={(e) => e.stopPropagation()}
                  >
                    terms
                  </a>{" "}
                  &amp; privacy policy. No spam, ever.
                </span>
              </label>

              {state === "error" && (
                <p className="text-xs text-red-600 font-medium px-1">{message}</p>
              )}

              <button
                type="submit"
                disabled={state === "loading"}
                className="w-full inline-flex items-center justify-center gap-2 rounded-2xl bg-accent text-accent-foreground px-6 py-3.5 text-sm font-semibold shadow-lg shadow-accent/20 hover:opacity-95 transition-all disabled:opacity-60"
              >
                {state === "loading" ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <Mail className="w-4 h-4" />
                )}
                Get Weekly Insights
              </button>
            </form>
          )}
        </div>
      </div>
    </div>
  );
}
